"""Tests for data generated by the spacecraft bus, instruments and targets."""

import pytest
from pydantic import ValidationError

from conops.common.enums import ACSMode
from conops.config import (
    DataGeneration,
    HousekeepingData,
    Instrument,
    MissionConfig,
    Payload,
    ScienceData,
    SpacecraftBus,
)
from conops.targets import PlanEntry


def _config() -> MissionConfig:
    """Three instruments and a bus, each generating data its own way."""
    return MissionConfig(
        spacecraft_bus=SpacecraftBus(
            data_generation=HousekeepingData(rate_gbps=0.001, rate_mode={"SAFE": 0.004})
        ),
        payload=Payload(
            instruments=[
                Instrument(
                    name="wide",
                    data_generation=DataGeneration(
                        science=ScienceData(rate_gbps=0.1),
                        housekeeping=HousekeepingData(rate_gbps=0.0005),
                    ),
                ),
                Instrument(
                    name="narrow",
                    data_generation=DataGeneration(
                        science=ScienceData(rate_gbps=0.02, per_observation_gb=1.0),
                        housekeeping=HousekeepingData(rate_mode={ACSMode.SAFE: 0.0}),
                    ),
                ),
                Instrument(
                    name="monitor",
                    data_generation=DataGeneration(
                        housekeeping=HousekeepingData(rate_gbps=0.002)
                    ),
                ),
            ]
        ),
    )


class TestScienceData:
    def test_an_observation_generates_its_rate_for_its_length_plus_a_fixed_amount(
        self,
    ) -> None:
        science = ScienceData(rate_gbps=0.1, per_observation_gb=5.0)
        assert science.data_generated(60) == pytest.approx(11.0)
        assert science.data_generated(120) == pytest.approx(17.0)
        assert science.data_generated(0) == pytest.approx(5.0)


class TestHousekeepingData:
    def test_rate_depends_on_mode(self) -> None:
        data = HousekeepingData(rate_gbps=0.001, rate_mode={"SAFE": 0.01, 2: 0.0})
        assert data.rate() == 0.001
        assert data.rate(ACSMode.SCIENCE) == 0.001
        assert data.rate(ACSMode.SAFE) == 0.01
        assert data.rate(ACSMode.SAA) == 0.0
        assert data.data_generated(60, mode=ACSMode.SAFE) == pytest.approx(0.6)

    def test_mode_rates_round_trip(self) -> None:
        data = HousekeepingData(rate_mode={"SAFE": 0.01})
        assert HousekeepingData.model_validate_json(data.model_dump_json()) == data

    @pytest.mark.parametrize(
        "modes", [{"NOT_A_MODE": 0.01}, {"SAFE": -0.01}, {99: 0.01}]
    )
    def test_rejects_bad_mode_rates(self, modes: dict[object, float]) -> None:
        with pytest.raises(ValidationError):
            HousekeepingData(rate_mode=modes)


class TestDataGeneration:
    def test_has_a_science_and_a_housekeeping_part(self) -> None:
        data = DataGeneration()
        assert data.science == ScienceData()
        assert data.housekeeping == HousekeepingData()

    def test_an_observation_collecting_for_the_whole_interval_by_default(
        self,
    ) -> None:
        data = DataGeneration(
            science=ScienceData(rate_gbps=0.1, per_observation_gb=5.0),
            housekeeping=HousekeepingData(rate_gbps=0.001),
        )
        assert data.data_generated(60) == pytest.approx(11.06)

    def test_housekeeping_for_the_whole_interval_science_for_the_collection(
        self,
    ) -> None:
        data = DataGeneration(
            science=ScienceData(rate_gbps=0.1, per_observation_gb=5.0),
            housekeeping=HousekeepingData(rate_gbps=0.001, rate_mode={"SAFE": 0.01}),
        )
        generated = data.data_generated(60, mode=ACSMode.SAFE, collection_seconds=20)
        assert generated == pytest.approx(0.01 * 60 + 0.1 * 20 + 5.0)

    def test_a_target_replaces_the_science_part_only(self) -> None:
        data = DataGeneration(
            science=ScienceData(rate_gbps=0.1, per_observation_gb=5.0),
            housekeeping=HousekeepingData(rate_gbps=0.001),
        )
        generated = data.data_generated(60, science=ScienceData(rate_gbps=0.3))
        assert generated == pytest.approx(0.001 * 60 + 0.3 * 60)

    def test_science_fields_given_directly_are_the_science_part(self) -> None:
        data = DataGeneration.model_validate(
            {"rate_gbps": 0.1, "per_observation_gb": 2.0}
        )
        assert data == DataGeneration(
            science=ScienceData(rate_gbps=0.1, per_observation_gb=2.0)
        )
        assert DataGeneration(rate_gbps=0.1).science.rate_gbps == 0.1

    def test_science_fields_go_in_one_place(self) -> None:
        with pytest.raises(ValidationError, match="inside 'science'"):
            DataGeneration(rate_gbps=0.1, science=ScienceData(rate_gbps=0.2))

    def test_saves_in_the_new_format(self) -> None:
        data = DataGeneration(science=ScienceData(rate_gbps=0.1))
        assert set(data.model_dump()) == {"science", "housekeeping"}


class TestPayload:
    def test_sums_the_instruments(self) -> None:
        payload = _config().payload
        assert payload.housekeeping_generated(60) == pytest.approx(0.0025 * 60)
        assert payload.science_generated(30) == pytest.approx(0.12 * 30 + 1.0)
        generated = payload.data_generated(60, collection_seconds=30)
        assert generated == pytest.approx(0.0025 * 60 + 0.12 * 30 + 1.0)

    def test_a_target_replaces_named_instruments_only(self) -> None:
        generated = _config().payload.science_generated(
            30,
            {
                "wide": ScienceData(rate_gbps=0.3),
                "monitor": ScienceData(rate_gbps=0.05),
            },
        )
        assert generated == pytest.approx((0.3 + 0.02 + 0.05) * 30 + 1.0)


class TestMissionConfig:
    def test_housekeeping_all_the_time(self) -> None:
        config = _config()
        assert config.housekeeping_generated(60, mode=ACSMode.SLEWING) == (
            pytest.approx(0.0035 * 60)
        )
        data = config.data_generated(60, mode=ACSMode.SLEWING, collection_seconds=0)
        assert data == pytest.approx(0.0035 * 60 + 1.0)

    def test_housekeeping_follows_the_mode(self) -> None:
        config = _config()
        data = config.housekeeping_generated(60, mode=ACSMode.SAFE)
        assert data == pytest.approx((0.004 + 0.0025) * 60)

    def test_an_observations_science_data_for_its_collection(self) -> None:
        config = _config()
        assert config.science_generated(30) == pytest.approx(0.12 * 30 + 1.0)
        data = config.data_generated(60, mode=ACSMode.SCIENCE, collection_seconds=30)
        assert data == pytest.approx(0.0035 * 60 + 0.12 * 30 + 1.0)

    def test_target_science_data(self) -> None:
        config = _config()
        data = config.data_generated(
            60,
            mode=ACSMode.SCIENCE,
            collection_seconds=30,
            science={"narrow": ScienceData(rate_gbps=0.5)},
        )
        assert data == pytest.approx(0.0035 * 60 + 0.6 * 30)

    def test_the_bus_generates_housekeeping_only(self) -> None:
        bus = _config().spacecraft_bus
        assert bus.data_generated(60, mode=ACSMode.SAFE) == pytest.approx(0.24)
        assert isinstance(bus.data_generation, HousekeepingData)

    def test_the_bus_rejects_an_instruments_data_generation(self) -> None:
        with pytest.raises(ValidationError):
            SpacecraftBus(data_generation=DataGeneration())

    def test_the_bus_rejects_science_fields(self) -> None:
        with pytest.raises(ValidationError, match="per_observation_gb"):
            SpacecraftBus.model_validate(
                {"data_generation": {"rate_gbps": 0.0, "per_observation_gb": 0.0}}
            )

    @pytest.mark.parametrize("mode", [ACSMode.SCIENCE, ACSMode.SAFE])
    def test_round_trips(self, mode: ACSMode) -> None:
        config = _config()
        loaded = MissionConfig.model_validate_json(config.model_dump_json())
        kwargs = {"mode": mode, "collection_seconds": 30}
        assert loaded.data_generated(60, **kwargs) == pytest.approx(
            config.data_generated(60, **kwargs)
        )


class TestTargetScienceData:
    def test_round_trips_with_a_plan_entry(self) -> None:
        entry = PlanEntry(science_data={"wide": ScienceData(rate_gbps=0.3)})
        loaded = PlanEntry.model_validate_json(entry.model_dump_json())
        assert loaded.science_data == entry.science_data

    def test_omitted_when_empty(self) -> None:
        assert "science_data" not in PlanEntry().model_dump()

    def test_unknown_instrument_is_rejected_with_a_config(self) -> None:
        with pytest.raises(ValidationError, match="'missing'"):
            PlanEntry(config=_config(), science_data={"missing": ScienceData()})
